\section{Introduction}

\subsection{Magnitude and its categorification}
Let $(X,d)$ be a finite metric space and $q$ a formal variable. The \emph{similarity matrix} of
$X$ is $Z=(q^{d(x,y)})_{x,y\in X}$, and when $Z$ is invertible the \emph{magnitude} of $X$ is the
sum of all entries of $Z^{-1}$. Leinster introduced this quantity as an ``effective number of
points'': it is multiplicative for $\ell^1$-products, additive for suitably transverse unions, and
in the continuous setting encodes volume, surface area and asymptotically even Minkowski
dimension.

For a finite connected graph $G$ with the shortest-path metric, magnitude is a rational function
of $q$ expanding as a power series with integer coefficients,
\[
  \#G(q)=\sum_{\ell\ge0}c_\ell(G)\,q^\ell .
\]
Hepworth and Willerton categorified this invariant: their \emph{magnitude homology}
$MH_{\ast,\ast}(G)$ is a bigraded abelian group with
\[
  \#G(q)=\sum_{k,\ell\ge0}(-1)^k\rank MH_{k,\ell}(G)\,q^\ell,
\]
so the magnitude power series is the graded Euler characteristic of a homology theory. Magnitude
homology sees strictly more than magnitude; it detects, for example, non-uniqueness of geodesics.

\subsection{Tope graphs}
A finite collection $\Acal=\{H_1,\dots,H_m\}$ of affine hyperplanes in $\RR^d$ cuts the complement
$\RR^d\setminus\bigcup_iH_i$ into finitely many connected components, the \emph{chambers} or
\emph{topes}. Two topes are adjacent when exactly one hyperplane of $\Acal$ separates them; the
resulting graph is the \emph{tope graph} $T(\Acal)$. Its metric is entirely combinatorial:

\begin{quote}
\textbf{Separation principle.} In the tope graph of a real hyperplane arrangement, the distance
between two topes equals the number of hyperplanes separating them.
\end{quote}

This is a theorem of Tits in the Coxeter setting and holds for all real arrangements, indeed for
all oriented matroids. Every finite Coxeter group $W$ has a reflection arrangement whose tope
graph is the Cayley graph $\Cay(W,S)$ with respect to the simple reflections, graph distance being
word length.

\subsection{The theorem being developed}
\begin{quote}
\textbf{Theorem (Magnitude homology of tope graphs).} For every real hyperplane arrangement
$\Acal$, the tope graph $T(\Acal)$ is \emph{diagonal}: $MH_{k,\ell}(T(\Acal))=0$ for $k\ne\ell$.
On the diagonal, $MH_{\ell,\ell}(T(\Acal))$ is free abelian of rank
$\sum_{T}H(k[\Delta_T];\ell)$, the sum over topes $T$ of the degree-$\ell$ value of the Hilbert
function of the Stanley--Reisner ring of a simplicial complex $\Delta_T$ canonically attached to
$T$. For central arrangements, a homological reciprocity relates ranks in complementary degrees.
\end{quote}
The general proof uses poset combinatorics of the covector poset, the Edelman--Walker theorem
identifying homotopy types of intervals as wedges of spheres, and Alexander duality translating
sphere counts into face counts, hence into Hilbert functions.

\subsection{What this paper does}
We give a self-contained, fully rigorous development for the \emph{coordinate (Boolean)
arrangement} $\Acal_n=\{x_i=0\}_{i=1}^n$ in $\RR^n$, together with structural theorems valid for
arbitrary connected graphs. Here every $\Delta_T$ is the full simplex on $n$ vertices, so
$k[\Delta_T]=k[x_1,\dots,x_n]$ and the predicted ranks are $2^n\binom{n+\ell-1}{\ell}$. We verify
this in bidegrees $(1,1)$ and $(2,2)$, prove off-diagonal vanishing in degree $1$ for all
connected graphs, and compute the degree-$2$ chain and cycle groups in every length. All metric
input reduces to a single dictionary --- \emph{separation $=$ symmetric difference} --- after which
the homological computations are pure enumeration.

\section{The magnitude chain complex}
Throughout, $G=(V,E)$ is a simple connected graph with shortest-path metric $d$.

\begin{definition}[Magnitude chains]
For $k,\ell\ge0$, a \emph{generator of bidegree $(k,\ell)$} is a tuple
$(x_0,\dots,x_k)\in V^{k+1}$ with $x_{i-1}\ne x_i$ for $i=1,\dots,k$ and
$\sum_{i=1}^kd(x_{i-1},x_i)=\ell$. The chain group $MC_{k,\ell}(G)$ is the free abelian group on
these generators.
\end{definition}

\begin{definition}[Differential]
For $1\le i\le k-1$ set
\[
  \partial_i(x_0,\dots,x_k)=
  \begin{cases}
    (x_0,\dots,\widehat{x_i},\dots,x_k) & \text{if } d(x_{i-1},x_i)+d(x_i,x_{i+1})=d(x_{i-1},x_{i+1}),\\
    0 & \text{otherwise,}
  \end{cases}
\]
and $\delta_k=\sum_{i=1}^{k-1}(-1)^i\partial_i\colon MC_{k,\ell}(G)\to MC_{k-1,\ell}(G)$. Then
$\delta_{k-1}\delta_k=0$ and $MH_{k,\ell}(G):=\ker\delta_k/\im\delta_{k+1}$.
\end{definition}

\begin{remark}[Length dominates degree]\label{rem:ldk}
In a connected graph $x\ne y$ implies $d(x,y)\ge1$, so a $(k,\ell)$-generator forces $\ell\ge k$;
the theory is supported in $\ell\ge k$.
\end{remark}

\begin{lemma}\label{lem:vanish}
Let $G$ be connected. Then $MC_{1,0}(G)=0$, $MC_{2,\ell}(G)=0$ for $\ell<2$, and
$MC_{3,\ell}(G)=0$ for $\ell<3$.
\end{lemma}
\begin{proof}
Each summand $d(x_{i-1},x_i)$ is strictly positive, so $\ell\ge k$ by Remark~\ref{rem:ldk}.
\end{proof}

\begin{definition}
$G$ is \emph{diagonal} if $MH_{k,\ell}(G)=0$ for all $k\ne\ell$.
\end{definition}

In low degrees we work with
$MC_{3,\ell}\xrightarrow{\delta_3}MC_{2,\ell}\xrightarrow{\delta_2}MC_{1,\ell}\xrightarrow{0}MC_{0,\ell}$,
where $\delta_2(x,y,z)=\pm(x,z)$ if $d(x,y)+d(y,z)=d(x,z)$ and $0$ otherwise. Since
$MC_{0,\ell}=0$ for $\ell\ge1$, we have $MH_{1,\ell}(G)=MC_{1,\ell}(G)/\im\delta_2$ for $\ell\ge1$.

\section{The coordinate arrangement and its chambers}
Fix $n\ge0$; let $\Acal_n$ be the arrangement of the hyperplanes $H_i=\{x\in\RR^n:x_i=0\}$.

\begin{definition}
For $s\subseteq\{1,\dots,n\}$ put
$C_s=\{x\in\RR^n: x_i>0 \text{ for } i\in s,\ x_i<0 \text{ for } i\notin s\}$.
\end{definition}

\begin{proposition}[Chamber geometry]\label{prop:chambers}
For every $s$: (i) $C_s\ne\emptyset$; (ii) $C_s$ is convex; (iii) $x_i\ne0$ for all $x\in C_s$ and
all $i$; (iv) $C_s\cap C_t=\emptyset$ whenever $s\ne t$.
\end{proposition}
\begin{proof}
(i) The sign vector $\varepsilon^s$ with $\varepsilon^s_i=1$ for $i\in s$ and $-1$ otherwise lies
in $C_s$. (ii) If $u,v>0$ and $a,b\ge0$ with $a+b=1$ then $au+bv>0$ (if $a=0$ then $b=1$ and
$au+bv=v>0$; otherwise $au>0$, $bv\ge0$). Apply this coordinatewise to $x_i,y_i$ for $i\in s$ and
to $-x_i,-y_i$ for $i\notin s$. (iii) Immediate from strictness. (iv) By
Theorem~\ref{thm:sep}, if $s\ne t$ then $s\sd t\ne\emptyset$, so $x\in C_s\cap C_t$ would give
$x_i^2<0$ for some $i$.
\end{proof}

\begin{theorem}[Separation equals symmetric difference]\label{thm:sep}
Let $x\in C_s$, $y\in C_t$ and $i\in\{1,\dots,n\}$. Then $i\in s\sd t$ if and only if $x_iy_i<0$,
i.e.\ iff $H_i$ separates $x$ from $y$. Consequently the set of hyperplanes separating $C_s$ from
$C_t$ is $\{H_i: i\in s\sd t\}$, of cardinality $|s\sd t|$.
\end{theorem}
\begin{proof}
Four cases. If $i\in s\cap t$ then $x_i,y_i>0$, so $x_iy_i>0$ and $i\notin s\sd t$. If
$i\notin s\cup t$ then $x_i,y_i<0$, so again $x_iy_i>0$ and $i\notin s\sd t$. If $i\in s\setminus
t$ then $x_i>0>y_i$, so $x_iy_i<0$ and $i\in s\sd t$; symmetrically for $i\in t\setminus s$.
\end{proof}

In particular the separation data do not depend on the representatives $x\in C_s$, $y\in C_t$ ---
a fact needed before the tope graph is even well defined.

\section{The tope graph is the hypercube}

\begin{definition}
The \emph{tope graph} $T_n$ of $\Acal_n$ has vertex set the subsets $s\subseteq\{1,\dots,n\}$,
with $s\sim t$ iff $|s\sd t|=1$.
\end{definition}

\begin{lemma}[Flip]\label{lem:flip}
For every $s$ and $i$, $s$ is adjacent to $s\sd\{i\}$, since $s\sd(s\sd\{i\})=\{i\}$.
\end{lemma}

\begin{lemma}[Descent step]\label{lem:step}
If $i\in s\sd t$ then $|(s\sd\{i\})\sd t|+1=|s\sd t|$.
\end{lemma}
\begin{proof}
$(s\sd\{i\})\sd t=(s\sd t)\sd\{i\}=(s\sd t)\setminus\{i\}$ because $i\in s\sd t$.
\end{proof}

\begin{theorem}[Metric identification]\label{thm:dist}
For all $s,t$ one has $d_{T_n}(s,t)=|s\sd t|$. In particular $T_n$ is connected and is isomorphic
as a metric graph to the $n$-cube $Q_n$ with the Hamming metric.
\end{theorem}
\begin{proof}
($\le$) Induct on $m=|s\sd t|$. If $m=0$ then $s=t$. Otherwise pick $i\in s\sd t$; by
Lemma~\ref{lem:flip}, $s\sim s'=s\sd\{i\}$ and by Lemma~\ref{lem:step} $|s'\sd t|=m-1$, so
induction gives a walk of length $\le m-1$ from $s'$ to $t$, and prepending the edge gives one of
length $\le m$.

($\ge$) Along any walk $s=u_0,\dots,u_L=t$ each step changes $|u_j\sd t|$ by exactly $1$, since
$u_{j+1}=u_j\sd\{i\}$ and $(u_j\sd\{i\})\sd t$ differs from $u_j\sd t$ by inserting or deleting
$i$. As $|u_L\sd t|=0$ and $|u_0\sd t|=|s\sd t|$, we get $L\ge|s\sd t|$.
\end{proof}

\begin{corollary}\label{cor:mc1}
For $\ell\ge1$, $\rank MC_{1,\ell}(T_n)=2^n\binom{n}{\ell}$. In particular $T_n$ has $2^nn$
ordered edges.
\end{corollary}
\begin{proof}
$(x,y)\mapsto(x,x\sd y)$ is a bijection from $(1,\ell)$-generators onto pairs (vertex, $\ell$-set
of coordinates), with inverse $(x,a)\mapsto(x,x\sd a)$; the condition $x\ne y$ becomes
$a\ne\emptyset$, automatic for $\ell\ge1$.
\end{proof}

\section{Structural results for arbitrary connected graphs}

\begin{theorem}[$MH_{1,1}$ is free on ordered edges]\label{thm:mh11}
For a connected graph $G$, $MH_{1,1}(G)$ is the free abelian group on the ordered edges
$\{(x,y): x\sim y\}$ of $G$.
\end{theorem}
\begin{proof}
By Lemma~\ref{lem:vanish}, $MC_{2,1}(G)=0$, so $\im\delta_2=0$ in length $1$, and the differential
out of degree $1$ vanishes. Hence $MH_{1,1}(G)=MC_{1,1}(G)$, free on pairs with $x\ne y$ and
$d(x,y)=1$, i.e.\ on ordered edges.
\end{proof}

\begin{lemma}[Geodesic first step]\label{lem:geo}
Let $G$ be connected with $d(x,y)\ge2$. Then there is $z$ with $x\sim z$, $z\ne y$ and
$d(x,z)+d(z,y)=d(x,y)$.
\end{lemma}
\begin{proof}
Take a walk of length $d(x,y)$ from $x$ to $y$; it is nonempty, so equals an edge $x\sim z$
followed by a walk of length $d(x,y)-1$ from $z$ to $y$. Then $d(x,z)=1$ and $d(z,y)\le d(x,y)-1$,
while the triangle inequality gives $d(x,y)\le1+d(z,y)$; hence $d(z,y)=d(x,y)-1$ and additivity
holds. If $z=y$ then $d(x,y)=1$, a contradiction.
\end{proof}

\begin{theorem}[Surjectivity of $\delta_2$]\label{thm:surj}
Let $G$ be connected and $\ell\ge2$. Then $\delta_2\colon MC_{2,\ell}(G)\to MC_{1,\ell}(G)$ is
surjective.
\end{theorem}
\begin{proof}
Given a generator $(x,y)$ with $d(x,y)=\ell\ge2$, Lemma~\ref{lem:geo} supplies $z$ with $x\sim z$,
$z\ne y$ and $d(x,z)+d(z,y)=\ell$. Then $(x,z,y)$ is a $(2,\ell)$-generator satisfying the
deletion condition, so $\delta_2(x,z,y)=\pm(x,y)$.
\end{proof}

\begin{corollary}[Degree-one diagonality]\label{cor:diag1}
For every connected graph $G$ and every $\ell\ge2$, $MH_{1,\ell}(G)=0$.
\end{corollary}

\begin{theorem}[Splitting]\label{thm:split}
For $G$ connected and $\ell\ge2$, $MC_{2,\ell}(G)\cong\ker\delta_2\oplus MC_{1,\ell}(G)$.
\end{theorem}
\begin{proof}
$MC_{1,\ell}(G)$ is free, hence projective, so the surjection of Theorem~\ref{thm:surj} splits:
$\delta_2\sigma=\mathrm{id}$ for some $\sigma$, and $MC_{2,\ell}=\ker\delta_2\oplus\im\sigma$ with
$\im\sigma\cong MC_{1,\ell}$.
\end{proof}

\begin{theorem}[Nothing maps into bidegree $(2,2)$]\label{thm:no3}
For $G$ connected, $MC_{3,2}(G)=0$; hence $\delta_3=0$ in length $2$ and
$MH_{2,2}(G)=\ker\bigl(\delta_2\colon MC_{2,2}(G)\to MC_{1,2}(G)\bigr)$.
\end{theorem}
\begin{proof}
A $(3,2)$-generator would need three strictly positive distances summing to $2$.
\end{proof}

\begin{theorem}[Rank formula]\label{thm:rank}
Let $G$ be connected with finitely many chains in bidegrees $(1,\ell)$, $(2,\ell)$ and let
$\ell\ge2$. Then $\ker\delta_2$ is free abelian and
$\rank\ker\delta_2+\rank MC_{1,\ell}(G)=\rank MC_{2,\ell}(G)$. In particular, for finite connected
$G$, $MH_{2,2}(G)\cong\ZZ^{\rank MC_{2,2}(G)-\rank MC_{1,2}(G)}$.
\end{theorem}
\begin{proof}
Theorem~\ref{thm:split} gives the rank identity, and a direct summand of a free module over the
principal ideal domain $\ZZ$ is free; Theorem~\ref{thm:no3} gives the last claim.
\end{proof}

\begin{theorem}[Diagonal cycles]\label{thm:diagcyc}
For $G$ connected, $(x,y)\mapsto(x,y,x)$ is an injection from ordered edges into
$\ker\delta_2\subseteq MC_{2,2}(G)$. Hence $MH_{2,2}(G)$ contains a free abelian subgroup of rank
the number of ordered edges; in particular it is nonzero whenever $G$ has an edge.
\end{theorem}
\begin{proof}
If $x\sim y$ then $(x,y,x)$ is a $(2,2)$-generator. Its deletion condition reads
$d(x,y)+d(y,x)=d(x,x)$, i.e.\ $2=0$, which fails, so $\delta_2(x,y,x)=0$. Injectivity is clear,
and distinct generators are part of a basis.
\end{proof}

\section{The magnitude homology of the coordinate arrangement}

\begin{theorem}[Degree-2 chains, all lengths]\label{thm:gen2}
For $\ell\ge1$ the $(2,\ell)$-generators of $T_n$ correspond bijectively to triples $(y,a,b)$ with
$y\subseteq\{1,\dots,n\}$ a tope and $a,b\subseteq\{1,\dots,n\}$ \emph{nonempty} with
$|a|+|b|=\ell$; the bijection sends $(x,y,z)$ to $(y,\,x\sd y,\,y\sd z)$.
\end{theorem}
\begin{proof}
Set $a=x\sd y$, $b=y\sd z$; by Theorem~\ref{thm:dist}, $|a|+|b|=\ell$, and $x\ne y$, $y\ne z$ say
exactly $a,b\ne\emptyset$. The inverse is $(y,a,b)\mapsto(y\sd a,\,y,\,y\sd b)$.
\end{proof}

\begin{lemma}[Vandermonde bijection]\label{lem:vdm}
Ordered pairs $(a,b)$ of subsets of an $n$-set with $|a|+|b|=\ell$ correspond bijectively to
$\ell$-subsets of a $2n$-set; there are $\binom{2n}{\ell}$ of them.
\end{lemma}
\begin{proof}
Identify the $2n$-set with a disjoint union of two copies of the $n$-set. Counting by $j=|a|$
recovers $\sum_j\binom{n}{j}\binom{n}{\ell-j}=\binom{2n}{\ell}$.
\end{proof}

\begin{lemma}\label{lem:empty}
For $\ell\ge1$, exactly $2\binom{n}{\ell}$ such pairs have an empty member.
\end{lemma}

\begin{theorem}[Chain ranks]\label{thm:chainranks}
For $\ell\ge1$,
\[
  \rank MC_{1,\ell}(T_n)=2^n\binom{n}{\ell},\qquad
  \rank MC_{2,\ell}(T_n)=2^n\left(\binom{2n}{\ell}-2\binom{n}{\ell}\right).
\]
In particular $\rank MC_{2,2}(T_n)=2^nn^2$.
\end{theorem}
\begin{proof}
The first is Corollary~\ref{cor:mc1}. For the second combine Theorem~\ref{thm:gen2} with
Lemmas~\ref{lem:vdm} and \ref{lem:empty}. For $\ell=2$,
$\binom{2n}{2}-2\binom{n}{2}=n(2n-1)-n(n-1)=n^2$; equivalently, a $(2,2)$-generator is a middle
vertex together with an ordered pair of its $n$ neighbours.
\end{proof}

\begin{theorem}[The diagonal in length two]\label{thm:mh22}
For every $n$, $MH_{2,2}(T_n)\cong\ZZ^{\,2^n\binom{n+1}{2}}$.
\end{theorem}
\begin{proof}
By Theorem~\ref{thm:no3}, $MH_{2,2}(T_n)=\ker\delta_2$, and by Theorem~\ref{thm:rank} this is free
of rank $2^nn^2-2^n\binom{n}{2}$. The identity $\binom{n}{2}+\binom{n+1}{2}=n^2$ --- both sides
count pairs $(i,j)\in\{1,\dots,n\}^2$, split by $i<j$ versus $i\ge j$ --- finishes the proof.
\end{proof}

\begin{theorem}[Cycles in arbitrary length]\label{thm:cycles}
For $\ell\ge2$ the group of $(2,\ell)$-cycles of $T_n$ is free abelian of rank
$2^n\bigl(\binom{2n}{\ell}-3\binom{n}{\ell}\bigr)$; for $\ell=2$ this equals
$2^n\binom{n+1}{2}$.
\end{theorem}

\subsection{Comparison with the Stanley--Reisner prediction}
For the coordinate arrangement each attached complex is the full simplex on the $n$ hyperplanes,
so $k[\Delta_T]=k[x_1,\dots,x_n]$ with Hilbert function
$H(k[x_1,\dots,x_n];\ell)=\binom{n+\ell-1}{\ell}$, and the predicted diagonal ranks are
$2^n\binom{n+\ell-1}{\ell}$.

\begin{center}
\begin{tabular}{ccc}
\toprule
$\ell$ & prediction & computed \\
\midrule
$1$ & $2^n n$ & $\rank MH_{1,1}(T_n)=2^nn$ (Thm.~\ref{thm:mh11}, Cor.~\ref{cor:mc1})\\
$2$ & $2^n\binom{n+1}{2}$ & $\rank MH_{2,2}(T_n)=2^n\binom{n+1}{2}$ (Thm.~\ref{thm:mh22})\\
\bottomrule
\end{tabular}
\end{center}

Off-diagonal vanishing in degree $1$ is Corollary~\ref{cor:diag1}. Conceptually, by
Theorem~\ref{thm:gen2} a degree-$k$ chain records at each tope an ordered tuple of nonempty
\emph{sets of hyperplanes}; passing to homology collapses the ordering and merges the tuple into a
multiset --- a monomial in the hyperplanes --- and the number of degree-$\ell$ monomials in $n$
variables is $\binom{n+\ell-1}{\ell}$.

\subsection{Homological reciprocity}
The coordinate arrangement is \emph{central}: all hyperplanes contain the origin, so the
arrangement is invariant under $x\mapsto-x$, which on topes is complementation
$s\mapsto\{1,\dots,n\}\setminus s$. Complementation is a distance-preserving automorphism of the
tope graph and therefore acts on all magnitude homology groups. The reciprocity phenomenon for
central arrangements --- a duality between ranks in complementary degrees, proved via Alexander
duality --- is the homological shadow of this antipodal involution. In the Boolean case the
involution is fixed-point free, and the resulting free $\ZZ/2$-action appears in every rank
formula through the factor $2^n=2\cdot2^{n-1}$.

\section{The Coxeter picture: the Cayley graph of $(\ZZ/2)^n$}

\begin{lemma}[Isomorphisms are isometries]\label{lem:iso}
If $e\colon G\to H$ is an isomorphism of simple graphs then $d_H(e(x),e(y))=d_G(x,y)$.
\end{lemma}
\begin{proof}
$e$ maps walks to walks of equal length, giving $\le$; apply the same to $e^{-1}$ for $\ge$.
\end{proof}

\begin{corollary}[Invariance]\label{cor:inv}
A graph isomorphism induces bijections of $(k,\ell)$-generators commuting with the differentials,
hence isomorphisms $MC_{k,\ell}(G)\cong MC_{k,\ell}(H)$, $\ker\delta_2^G\cong\ker\delta_2^H$ and
$MH_{k,\ell}(G)\cong MH_{k,\ell}(H)$.
\end{corollary}

\begin{definition}
Let $W_n=(\ZZ/2)^n$, the Coxeter group of type $A_1^n$, with standard generating set
$S=\{e_1,\dots,e_n\}$ of coordinate reflections. The Cayley graph $\Cay(W_n,S)$ has vertex set
$W_n$ and an edge between $g$ and $h$ whenever $g+h=e_i$ for some $i$.
\end{definition}

\begin{theorem}[Tope graph $=$ Coxeter Cayley graph]\label{thm:cayley}
The indicator map $\iota(s)=(\mathbf 1[1\in s],\dots,\mathbf 1[n\in s])$ is an isomorphism of
graphs $T_n\to\Cay(W_n,S)$.
\end{theorem}
\begin{proof}
$\iota$ is bijective (a subset is the support of its indicator), satisfies
$\iota(s\sd t)=\iota(s)+\iota(t)$ and $\iota(\{i\})=e_i$; hence $|s\sd t|=1$ iff
$\iota(s)+\iota(t)=e_i$ for some $i$.
\end{proof}

\begin{corollary}[Magnitude homology of $(\ZZ/2)^n$]\label{cor:cay}
Let $C_n=\Cay((\ZZ/2)^n,\{e_i\})$. Then:
\begin{enumerate}
\item[(i)] $C_n$ is connected and its distance is word length, $d(\iota s,\iota t)=|s\sd t|$;
\item[(ii)] $\rank MC_{1,\ell}(C_n)=2^n\binom{n}{\ell}$, and $C_n$ has $2^nn$ ordered edges;
\item[(iii)] $MH_{1,1}(C_n)$ is free abelian of rank $2^nn$, on the ordered edges;
\item[(iv)] $MH_{1,\ell}(C_n)=0$ for all $\ell\ge2$;
\item[(v)] $MH_{2,2}(C_n)\cong\ZZ^{\,2^n\binom{n+1}{2}}$, nonzero for $n\ge1$;
\item[(vi)] for $\ell\ge2$ the $(2,\ell)$-cycle group is free of rank
      $2^n\bigl(\binom{2n}{\ell}-3\binom{n}{\ell}\bigr)$.
\end{enumerate}
\end{corollary}
\begin{proof}
Combine Theorem~\ref{thm:cayley} and Corollary~\ref{cor:inv} with
Theorems~\ref{thm:dist}, \ref{thm:mh11}, \ref{thm:diagcyc}, \ref{thm:chainranks},
\ref{thm:mh22}, \ref{thm:cycles} and Corollary~\ref{cor:diag1}.
\end{proof}

\section{Algorithms}

\textbf{Algorithm A (tope-graph metric).} Input $n$ and bitmasks $s,t$; output $d(s,t)$ as the
population count of $s\oplus t$. Cost $O(1)$ machine words, $O(n)$ bit operations. Correctness is
Theorem~\ref{thm:dist}. This replaces a breadth-first search over $2^n$ vertices.

\textbf{Algorithm B (chain ranks).} Input $n$, $k\in\{1,2\}$, $\ell$; return $2^n\binom{n}{\ell}$
for $k=1$ and $2^n\bigl(\binom{2n}{\ell}-2\binom{n}{\ell}\bigr)$ for $k=2$. Cost $O(\ell)$
big-integer multiplications. Correctness is Theorem~\ref{thm:chainranks}.

\textbf{Algorithm C (rank of $\ker\delta_2$ for an arbitrary finite graph).} Compute all-pairs
distances by breadth-first search, enumerate the $(2,\ell)$- and $(1,\ell)$-generators, and return
$\#MC_{2,\ell}-\rank\delta_2$. Because $\delta_2$ sends each basis vector either to $0$ or to a
\emph{single} basis vector, its rank equals the number of distinct targets hit, so the
computation is linear in the number of chains rather than cubic: $O(|V|(|V|+|E|))$ for the metric
and $O(\#MC_{2,\ell})$ thereafter.

\section{Applications and discussion}

\textbf{Computability of magnitude.} Diagonality collapses the alternating sum to one term per
length: $\#G(q)=\sum_{\ell}(-1)^\ell\rank MH_{\ell,\ell}(G)q^\ell$. For $T_n$ this gives
\[
  \#T_n(q)=2^n\sum_{\ell\ge0}(-1)^\ell\binom{n+\ell-1}{\ell}q^\ell=\frac{2^n}{(1+q)^n},
\]
matching the classical computation of the magnitude of the hypercube as the $n$-fold
$\ell^1$-product of the two-point space of magnitude $2/(1+q)$ --- a strong consistency check on
all ranks above.

\textbf{Coxeter groups.} The identification of tope graphs of reflection arrangements with Cayley
graphs turns geometry into group theory: the magnitude homology of a finite Coxeter group with
word metric is diagonal, with ranks given by Hilbert functions distributed over group elements.
The case $(\ZZ/2)^n$ treated here is the base case; the same architecture applies to types
$A_{n-1}$, $B_n$, $D_n$ and the exceptional types, where the attached complexes are not simplices
and the Hilbert functions are those of genuinely nontrivial Stanley--Reisner rings.

\textbf{Oriented matroids.} Nothing in Sections 3--4 used the ambient $\RR^n$ beyond sign vectors;
the separation principle is a statement about covectors, so tope graphs of oriented matroids
inherit the theory.

\textbf{Limits of the present development.} We prove diagonality in degree $1$ for all connected
graphs and compute the diagonal in bidegree $(2,2)$ exactly, plus the ranks of all
$(2,\ell)$-cycle groups of the tope graph. Full diagonality --- $MH_{k,\ell}(T_n)=0$ for all
$k\ne\ell$ --- and the rank $2^n\binom{n+\ell-1}{\ell}$ on the diagonal for $\ell\ge3$ require the
higher differentials and the filtration argument sketched in Section 1.

\section{Future work}
\begin{enumerate}
\item Extend the chain-level analysis from degrees $\le2$ to arbitrary degree, establishing full
diagonality of the hypercube and the rank formula $2^n\binom{n+\ell-1}{\ell}$ directly.
\item Replace the Boolean arrangement by an arbitrary real arrangement: build the covector poset,
its intervals and order complexes, and carry through the Edelman--Walker/Alexander-duality
argument.
\item Compute the attached complexes and their Stanley--Reisner rings for the symmetric and
hyperoctahedral groups and compare with independently computed magnitude series.
\item Formulate the homological reciprocity for central arrangements as an isomorphism of graded
groups induced by the antipodal involution, and identify the sign character.
\item Axiomatise the argument for tope graphs of arbitrary, possibly non-realisable, oriented
matroids.
\item Determine whether the magnitude homology of tope graphs is torsion-free in all degrees.
\end{enumerate}

\end{document}

