"""Demo: geodesics, the antipodal involution, and homological reciprocity.

The coordinate arrangement in R^n is *central*: every hyperplane passes through
the origin, so the arrangement is invariant under x -> -x.  On topes this is
complementation s -> {1,...,n} \\ s, which sends each orthant to the opposite
one.  This script demonstrates, by direct computation:

  1. Complementation is a distance-preserving automorphism of the tope graph
     (so it acts on every magnitude homology group) and is fixed-point free.
  2. It exchanges the two ends of every diameter: d(s, s^c) = n for all s.
  3. The number of geodesics between two topes is k! where k is the number of
     separating hyperplanes; summing over all ordered pairs gives the total
     geodesic count sum_k C(n,k) k! * 2^n.
  4. The interval structure behind the Hilbert-function answer: the set of
     topes lying on some geodesic between s and t is a Boolean lattice of rank
     |s XOR t|, i.e. a subcube; its cardinality is 2^{d(s,t)}.
  5. The magnitude power series of the tope graph, computed two ways: from the
     diagonal ranks 2^n C(n+l-1, l), and by inverting the similarity matrix
     Z = (q^{d(s,t)}) exactly over the rationals at a sample value of q.

Run:  python3 demo2.py
"""

from __future__ import annotations

from fractions import Fraction
from itertools import product
from math import comb, factorial
from typing import List, Tuple


def popcount(m: int) -> int:
    return bin(m).count("1")


def dist(s: int, t: int) -> int:
    """Tope-graph distance = number of separating hyperplanes."""
    return popcount(s ^ t)


def complement(s: int, n: int) -> int:
    """The antipodal tope: negate every coordinate."""
    return s ^ ((1 << n) - 1)


def interval(s: int, t: int) -> List[int]:
    """Topes lying on some geodesic from s to t: the subcube spanned by s XOR t."""
    diff = [i for i in range(s.bit_length() | t.bit_length() | 1) if ((s ^ t) >> i) & 1]
    out = []
    for bits in product([0, 1], repeat=len(diff)):
        v = s
        for b, i in zip(bits, diff):
            if b:
                v ^= 1 << i
        out.append(v)
    return out


def check_antipodal(n: int) -> Tuple[bool, bool, bool]:
    """(is an automorphism, is an isometry, is fixed-point free)."""
    auto = all(
        dist(s, t) == 1
        for s in range(1 << n)
        for t in range(1 << n)
        if dist(complement(s, n), complement(t, n)) == 1
    )
    isom = all(
        dist(complement(s, n), complement(t, n)) == dist(s, t)
        for s in range(1 << n)
        for t in range(1 << n)
    )
    free = all(complement(s, n) != s for s in range(1 << n)) if n >= 1 else True
    return auto, isom, free


def total_geodesics(n: int) -> int:
    """Sum over ordered pairs of topes of the number of shortest paths."""
    return sum(
        factorial(dist(s, t)) for s in range(1 << n) for t in range(1 << n)
    )


def total_geodesics_formula(n: int) -> int:
    """Closed form: 2^n * sum_k C(n,k) k!."""
    return (1 << n) * sum(comb(n, k) * factorial(k) for k in range(n + 1))


def similarity_magnitude(n: int, q: Fraction) -> Fraction:
    """Magnitude of the tope graph at a rational q, by inverting Z exactly.

    Solves Z w = 1 with exact rational arithmetic (Gaussian elimination) and
    returns the sum of the entries of w, which is the magnitude.
    """
    size = 1 << n
    mat: List[List[Fraction]] = [
        [q ** dist(s, t) for t in range(size)] + [Fraction(1)] for s in range(size)
    ]
    for col in range(size):
        pivot = next(r for r in range(col, size) if mat[r][col] != 0)
        mat[col], mat[pivot] = mat[pivot], mat[col]
        pv = mat[col][col]
        mat[col] = [x / pv for x in mat[col]]
        for r in range(size):
            if r != col and mat[r][col] != 0:
                f = mat[r][col]
                mat[r] = [a - f * b for a, b in zip(mat[r], mat[col])]
    return sum(mat[r][size] for r in range(size))


def magnitude_closed_form(n: int, q: Fraction) -> Fraction:
    """2^n / (1+q)^n, the value predicted by the diagonal ranks."""
    return Fraction(1 << n) / (1 + q) ** n


def main() -> None:
    print("1-2. The antipodal involution s -> complement(s)")
    for n in range(1, 7):
        auto, isom, free = check_antipodal(n)
        diam = all(dist(s, complement(s, n)) == n for s in range(1 << n))
        print(f"   n={n}: automorphism={auto}, isometry={isom}, "
              f"fixed-point free={free}, d(s, s^c)=n for all s: {diam}")

    print("\n3. Counting geodesics")
    for n in range(1, 7):
        a, b = total_geodesics(n), total_geodesics_formula(n)
        print(f"   n={n}: total shortest paths = {a}  "
              f"(closed form 2^n sum_k C(n,k) k! = {b})  match={a == b}")

    print("\n4. Geodesic intervals are subcubes")
    for n in range(1, 6):
        ok = all(
            len(interval(s, t)) == 2 ** dist(s, t)
            and all(dist(s, u) + dist(u, t) == dist(s, t) for u in interval(s, t))
            for s in range(1 << n)
            for t in range(1 << n)
        )
        print(f"   n={n}: every interval [s,t] is a Boolean subcube of size "
              f"2^d(s,t): {ok}")

    print("\n5. Magnitude, two ways")
    for q in (Fraction(1, 2), Fraction(1, 3), Fraction(2, 5)):
        for n in range(1, 5):
            a = similarity_magnitude(n, q)
            b = magnitude_closed_form(n, q)
            print(f"   q={q}, n={n}: from similarity matrix = {a}, "
                  f"from diagonal ranks = {b}, match={a == b}")


if __name__ == "__main__":
    main()

