"""Algorithm A: the separation metric of the tope graph of the coordinate arrangement.

The separation principle says that the distance between two chambers of a real
hyperplane arrangement equals the number of hyperplanes separating them.  For
the arrangement of the n coordinate hyperplanes in R^n, the chamber indexed by
a subset s (the coordinates that are positive) is separated from the chamber
indexed by t exactly along the coordinates in the symmetric difference s XOR t.

Hence the graph distance -- normally an O(V + E) breadth-first search over
2^n vertices -- collapses to a single population count.
"""

from __future__ import annotations

from typing import Dict, List, Sequence, Set, Tuple


def separating_hyperplanes_from_points(
    x: Sequence[float], y: Sequence[float]
) -> Set[int]:
    """Indices i with x_i * y_i < 0, i.e. hyperplanes {x_i = 0} separating x, y."""
    return {i for i, (xi, yi) in enumerate(zip(x, y)) if xi * yi < 0.0}


def chamber_index(x: Sequence[float]) -> int:
    """Bitmask of the chamber containing x (bit i set iff x_i > 0).

    Raises ValueError if x lies on a hyperplane of the arrangement.
    """
    mask = 0
    for i, xi in enumerate(x):
        if xi == 0.0:
            raise ValueError(f"point lies on hyperplane x_{i} = 0")
        if xi > 0.0:
            mask |= 1 << i
    return mask


def separation_set(s: int, t: int, n: int) -> Set[int]:
    """The set of hyperplane indices separating the chambers s and t."""
    d = s ^ t
    return {i for i in range(n) if (d >> i) & 1}


def tope_distance(s: int, t: int) -> int:
    """Graph distance in the tope graph: the number of separating hyperplanes."""
    return bin(s ^ t).count("1")


def geodesic(s: int, t: int, n: int) -> List[int]:
    """A shortest path in the tope graph, crossing each separating wall once."""
    path = [s]
    current = s
    for i in sorted(separation_set(s, t, n)):
        current ^= 1 << i
        path.append(current)
    return path


def count_geodesics(s: int, t: int) -> int:
    """Number of shortest paths from s to t: (number of separating walls)!."""
    k = tope_distance(s, t)
    result = 1
    for j in range(2, k + 1):
        result *= j
    return result


def verify_against_bfs(n: int) -> bool:
    """Check the closed form against breadth-first search on the whole graph."""
    from collections import deque

    adj: Dict[int, List[int]] = {
        v: [v ^ (1 << i) for i in range(n)] for v in range(1 << n)
    }
    for source in adj:
        dist = {source: 0}
        queue: deque[int] = deque([source])
        while queue:
            v = queue.popleft()
            for w in adj[v]:
                if w not in dist:
                    dist[w] = dist[v] + 1
                    queue.append(w)
        if any(dist[t] != tope_distance(source, t) for t in adj):
            return False
    return True


if __name__ == "__main__":
    n = 4
    print("verified against BFS:", verify_against_bfs(n))
    s, t = 0b0000, 0b1011
    print("separating hyperplanes:", sorted(separation_set(s, t, n)))
    print("distance:", tope_distance(s, t))
    print("a geodesic:", [format(v, f"0{n}b") for v in geodesic(s, t, n)])
    print("number of geodesics:", count_geodesics(s, t))

"""Algorithm B: closed-form ranks of the magnitude chain, cycle and homology groups.

For the tope graph T_n of the n coordinate hyperplanes in R^n (equivalently the
n-cube, equivalently the Cayley graph of the Coxeter group (Z/2)^n):

    rank MC_{1,l}      = 2^n * C(n, l)
    rank MC_{2,l}      = 2^n * (C(2n, l) - 2 C(n, l))
    rank ker delta_2   = 2^n * (C(2n, l) - 3 C(n, l))          (l >= 2)
    rank MH_{2,2}      = 2^n * C(n+1, 2)                        (l = 2)
    predicted diagonal = 2^n * C(n+l-1, l)   (Hilbert function of k[x_1..x_n])

Each evaluation costs O(l) big-integer multiplications, in contrast with the
O(4^n) enumeration of chains that the definitions suggest.
"""

from __future__ import annotations

from fractions import Fraction
from math import comb
from typing import List, Tuple


def rank_mc1(n: int, ell: int) -> int:
    """Rank of the degree-1 magnitude chain group of length l."""
    if ell < 1:
        return 0
    return (1 << n) * comb(n, ell)


def rank_mc2(n: int, ell: int) -> int:
    """Rank of the degree-2 magnitude chain group of length l."""
    if ell < 2:
        return 0
    return (1 << n) * (comb(2 * n, ell) - 2 * comb(n, ell))


def rank_cycles2(n: int, ell: int) -> int:
    """Rank of the (2,l)-cycle group ker delta_2, valid for l >= 2."""
    if ell < 2:
        return 0
    return (1 << n) * (comb(2 * n, ell) - 3 * comb(n, ell))


def hilbert_polynomial_ring(n: int, ell: int) -> int:
    """Hilbert function of the polynomial ring k[x_1,...,x_n] in degree l."""
    return comb(n + ell - 1, ell)


def rank_diagonal(n: int, ell: int) -> int:
    """Stanley-Reisner prediction for rank MH_{l,l}(T_n)."""
    return (1 << n) * hilbert_polynomial_ring(n, ell)


def rank_mh(n: int, k: int, ell: int) -> int:
    """Ranks of magnitude homology that the development determines exactly."""
    if k == 1 and ell == 1:
        return (1 << n) * n
    if k == 1 and ell >= 2:
        return 0
    if k == 2 and ell == 2:
        return rank_cycles2(n, 2)
    raise NotImplementedError(f"bidegree ({k},{ell}) not determined here")


def magnitude_series(n: int, order: int) -> List[int]:
    """Coefficients of the magnitude power series of T_n up to q^order.

    Diagonality collapses the graded Euler characteristic to one term per
    length, giving 2^n / (1+q)^n.
    """
    return [(-1) ** ell * rank_diagonal(n, ell) for ell in range(order + 1)]


def magnitude_at(n: int, q: Fraction) -> Fraction:
    """Exact magnitude of T_n at a rational q with q != -1."""
    return Fraction(1 << n, 1) / (1 + q) ** n


def rank_table(nmax: int, lmax: int) -> List[Tuple[int, int, int, int, int]]:
    """Table of (n, l, rank MC_1l, rank MC_2l, rank ker delta_2)."""
    return [
        (n, ell, rank_mc1(n, ell), rank_mc2(n, ell), rank_cycles2(n, ell))
        for n in range(1, nmax + 1)
        for ell in range(2, lmax + 1)
    ]


if __name__ == "__main__":
    print(f"{'n':>2} {'l':>2} {'MC_1l':>8} {'MC_2l':>8} {'ker d2':>8}")
    for row in rank_table(5, 5):
        print(f"{row[0]:>2} {row[1]:>2} {row[2]:>8} {row[3]:>8} {row[4]:>8}")
    print()
    for n in range(1, 5):
        print(f"n={n}:  MH_22 rank = {rank_mh(n, 2, 2)}"
              f" = 2^{n} * C({n+1},2) = {rank_diagonal(n, 2)}")
        print(f"      magnitude series: {magnitude_series(n, 5)}")
        print(f"      magnitude at q=1/2: {magnitude_at(n, Fraction(1, 2))}")

"""Algorithm C: exact rank of the degree-2 magnitude differential of any finite graph.

The degree-2 magnitude differential delta_2 sends a generator (x, y, z) either
to 0 (when the middle vertex y forces a detour) or to the single generator
(x, z) (when y lies on a geodesic from x to z).  A matrix all of whose columns
are zero or a standard basis vector has rank equal to the number of DISTINCT
basis vectors appearing, so the rank can be computed by hashing rather than by
Gaussian elimination.

Complexity:
    all-pairs distances     O(|V| (|V| + |E|))   (breadth-first search)
    enumeration of chains   O(#MC_{2,l})
    rank of delta_2         O(#MC_{2,l}) expected, by hashing
compared with O((#MC_{2,l})^3) for naive elimination.

Since nothing maps into bidegree (2,2) (a three-legged journey has length at
least 3), for l = 2 the kernel IS the magnitude homology MH_{2,2}(G).
"""

from __future__ import annotations

from collections import deque
from typing import Dict, Iterable, List, Optional, Set, Tuple

Graph = Dict[int, List[int]]


def all_pairs_distances(graph: Graph) -> Dict[int, Dict[int, int]]:
    """All-pairs shortest-path distances by repeated breadth-first search."""
    result: Dict[int, Dict[int, int]] = {}
    for source in graph:
        dist: Dict[int, int] = {source: 0}
        queue: deque[int] = deque([source])
        while queue:
            v = queue.popleft()
            for w in graph[v]:
                if w not in dist:
                    dist[w] = dist[v] + 1
                    queue.append(w)
        result[source] = dist
    return result


def generators_degree1(
    dist: Dict[int, Dict[int, int]], ell: int
) -> List[Tuple[int, int]]:
    """Generators of MC_{1,l}: ordered pairs of distinct vertices at distance l."""
    return [(x, y) for x in dist for y in dist if x != y and dist[x].get(y) == ell]


def generators_degree2(
    dist: Dict[int, Dict[int, int]], ell: int
) -> List[Tuple[int, int, int]]:
    """Generators of MC_{2,l}: triples (x,y,z) with x != y != z, legs summing to l."""
    out: List[Tuple[int, int, int]] = []
    for y in dist:
        for x in dist:
            if x == y:
                continue
            a = dist[x].get(y)
            if a is None or a >= ell:
                continue
            for z in dist:
                if z == y:
                    continue
                b = dist[y].get(z)
                if b is not None and a + b == ell:
                    out.append((x, y, z))
    return out


def delta2(
    dist: Dict[int, Dict[int, int]], triple: Tuple[int, int, int]
) -> Optional[Tuple[int, int]]:
    """Image of a (2,l)-generator under the magnitude differential (up to sign)."""
    x, y, z = triple
    if x == z:
        return None
    if dist[x][y] + dist[y][z] == dist[x][z]:
        return (x, z)
    return None


def magnitude_ranks(graph: Graph, ell: int) -> Dict[str, int]:
    """Ranks of MC_{2,l}, MC_{1,l}, im delta_2 and ker delta_2 for a finite graph."""
    dist = all_pairs_distances(graph)
    g2 = generators_degree2(dist, ell)
    g1 = generators_degree1(dist, ell)
    hit: Set[Tuple[int, int]] = set()
    for triple in g2:
        image = delta2(dist, triple)
        if image is not None:
            hit.add(image)
    return {
        "mc2": len(g2),
        "mc1": len(g1),
        "rank_image": len(hit),
        "rank_kernel": len(g2) - len(hit),
        "surjective": int(len(hit) == len(g1)),
    }


def mh22_rank(graph: Graph) -> int:
    """Rank of MH_{2,2}(G) for a finite connected graph."""
    return magnitude_ranks(graph, 2)["rank_kernel"]


def hypercube(n: int) -> Graph:
    """The n-cube: the tope graph of the n coordinate hyperplanes in R^n."""
    return {s: [s ^ (1 << i) for i in range(n)] for s in range(1 << n)}


def cycle(m: int) -> Graph:
    return {i: [(i - 1) % m, (i + 1) % m] for i in range(m)}


if __name__ == "__main__":
    for n in range(1, 5):
        info = magnitude_ranks(hypercube(n), 2)
        print(f"Q_{n}: {info}   (expected MH_22 rank = {(1 << n) * (n * (n + 1) // 2)})")
    for m in (4, 5, 6, 7):
        print(f"C_{m}: MH_22 rank = {mh22_rank(cycle(m))}")
